(()=>{const root=document.querySelector('.trouble-show');if(!root)return;const scenes=[...root.querySelectorAll('.trouble-scene')],dots=[...root.querySelectorAll('[data-pick]')],pause=root.querySelector('#trouble-pause'),reduce=matchMedia('(prefers-reduced-motion: reduce)');let index=0,timer=null,stopped=reduce.matches,visible=true;function show(n){index=n;scenes.forEach((s,i)=>{s.classList.toggle('is-active',i===n);s.setAttribute('aria-hidden',String(i!==n))});dots.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===n)))}function sync(){clearInterval(timer);root.classList.toggle('motion-off',stopped||reduce.matches||document.hidden||!visible);pause.textContent=stopped?'Play':'Pause';pause.setAttribute('aria-label',stopped?'Play animated showcase':'Pause animated showcase');if(!stopped&&visible&&!document.hidden)timer=setInterval(()=>show((index+1)%scenes.length),6500)}dots.forEach(b=>b.addEventListener('click',()=>{show(Number(b.dataset.pick));stopped=true;sync()}));pause.addEventListener('click',()=>{stopped=!stopped;sync()});root.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();show((index+(e.key==='ArrowRight'?1:2))%3);stopped=true;sync()}});reduce.addEventListener('change',()=>{stopped=reduce.matches;sync()});document.addEventListener('visibilitychange',sync);new IntersectionObserver(e=>{visible=e[0].isIntersecting;sync()},{threshold:.05}).observe(root);show(0);sync()})();
(()=>{const form=document.getElementById('mortgage-check'),result=document.getElementById('check-result');if(!form||!result)return;const titles={buy:"Let’s like the payment as much as the house.",refi:"Let’s see whether your mortgage needs touching.",review:"Page two deserves a second set of eyes."},bodies={buy:"Start with a budget conversation before the house hunt makes things emotional. Then we can talk documents, loan options, and next steps.",refi:"Bring your current loan details and your goal. We’ll compare the costs, term, and tradeoffs of changing it. Doing nothing is still an option.",review:"We can walk through your Loan Estimate together. Contact me first so we can arrange a secure way to share documents."},questions={payment:"What would my total monthly payment include, and what could change?",cash:"What would I need for the down payment, closing costs, and reserves?",surprises:"What still needs to happen, what could hold this up, and when will I hear from you?"},timing={soon:"If you have a closing date or contract deadline, tell me that first. Call 623-696-8683 to discuss the timeline.",later:"You have time to prepare. Let’s use it to sort out the questions before you’re also sorting moving boxes.",looking:"You can look around without making a commitment. Bring the questions; leave the pressure."};form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const a=new FormData(form),goal=a.get('goal');document.getElementById('result-title').textContent=titles[goal];document.getElementById('result-body').textContent=bodies[goal];document.getElementById('result-timing').textContent=timing[a.get('when')];document.getElementById('result-question').textContent=questions[a.get('worry')];const link=document.getElementById('result-link');link.href=goal==='review'?'/double_checker/':goal==='refi'?'/refinance/':'/buy/';link.textContent=goal==='review'?'Get my offer reviewed ↗':goal==='refi'?'Review my mortgage ↗':'Plan my home purchase ↗';form.hidden=true;result.hidden=false;result.focus()});document.getElementById('check-reset').addEventListener('click',()=>{result.hidden=true;form.hidden=false;form.querySelector('input').focus()})})();
